     1	package githelper
     2	
     3	import (
     4		"bufio"
     5		"context"
     6		"errors"
     7		"fmt"
     8		"io"
     9		"strings"
    10	
    11		"github.com/go-git/go-git/v6/plumbing/format/pktline"
    12		"github.com/go-git/go-git/v6/plumbing/protocol/packp"
    13	)
    14	
    15	// handleList implements the git-remote-helpers "list" / "list for-push"
    16	// command. It fetches the v0 info/refs advertisement, extracts each
    17	// ref and HEAD's symref target from the embedded capabilities, and
    18	// writes one "<value> <name>" line per ref followed by a blank-line
    19	// terminator. HEAD is emitted as "@<target> HEAD" when the symref
    20	// capability resolves; detached HEAD falls back to "<sha> HEAD".
    21	func handleList(ctx context.Context, t Transport, adv *refAdvCache, forPush bool, stdout io.Writer) error {
    22		service := serviceUploadPack
    23		if forPush {
    24			service = serviceReceivePack
    25		}
    26		refs, err := adv.infoRefs(ctx, t, service)
    27		if err != nil {
    28			return fmt.Errorf("list %s info/refs: %w", service, err)
    29		}
    30		defer refs.Close()
    31	
    32		r := bufio.NewReader(refs)
    33		var reply packp.SmartReply
    34		if err := reply.Decode(r); err != nil {
    35			return fmt.Errorf("parsing info/refs: %w", err)
    36		}
    37	
    38		type entry struct{ value, name string }
    39		var (
    40			lines        []entry
    41			headValue    string
    42			objectFormat string
    43			symrefs      = map[string]string{}
    44			first        = true
    45		)
    46		for {
    47			_, content, err := pktline.ReadLine(r)
    48			if err != nil {
    49				if errors.Is(err, io.EOF) {
    50					break
    51				}
    52				return fmt.Errorf("reading ref pkt-line: %w", err)
    53			}
    54			if len(content) == 0 {
    55				// Flush, delim, or response-end. For the v0 ref
    56				// advertisement only flush is meaningful — it ends
    57				// the list.
    58				break
    59			}
    60			line := strings.TrimRight(string(content), "\n")
    61	
    62			// The first advertised ref carries the capability list after a
    63			// NUL separator: "<sha> <ref>\0<cap1> <cap2> ...". Subsequent
    64			// refs are bare. We pluck every symref=src:dst pair and
    65			// object-format=<hash> out of those caps; the rest is for the
    66			// smart-transport client only.
    67			if first {
    68				first = false
    69				var caps string
    70				if i := strings.IndexByte(line, 0); i >= 0 {
    71					caps = line[i+1:]
    72					line = line[:i]
    73				}
    74				for c := range strings.FieldsSeq(caps) {
    75					switch {
    76					case strings.HasPrefix(c, "object-format="):
    77						objectFormat = strings.TrimPrefix(c, "object-format=")
    78					case strings.HasPrefix(c, "symref="):
    79						if src, dst, ok := strings.Cut(strings.TrimPrefix(c, "symref="), ":"); ok {
    80							symrefs[src] = dst
    81						}
    82					}
    83				}
    84			}
    85	
    86			value, name, ok := strings.Cut(line, " ")
    87			if !ok {
    88				continue
    89			}
    90			// Empty repos are advertised with a single dummy ref
    91			// "<null-oid> capabilities^{}" so the server still gets a
    92			// chance to send its capability list. Skip it — it's not a
    93			// real ref and transport-helper would reject the name.
    94			if name == "capabilities^{}" {
    95				continue
    96			}
    97			if name == "HEAD" {
    98				headValue = value
    99				continue
   100			}
   101			lines = append(lines, entry{value, name})
   102		}
   103	
   104		if objectFormat != "" {
   105			if _, err := fmt.Fprintf(stdout, ":object-format %s\n", objectFormat); err != nil {
   106				return fmt.Errorf("writing object-format: %w", err)
   107			}
   108		}
   109		for _, l := range lines {
   110			value := l.value
   111			if target, ok := symrefs[l.name]; ok {
   112				value = "@" + target
   113			}
   114			if _, err := fmt.Fprintf(stdout, "%s %s\n", value, l.name); err != nil {
   115				return fmt.Errorf("writing ref: %w", err)
   116			}
   117		}
   118		// Emit HEAD whenever we know something about it: either a SHA
   119		// (normal or detached HEAD) or a symref target (unborn HEAD on an
   120		// empty repo where the server advertises
   121		// symref=HEAD:refs/heads/main but no SHA). transport-helper.c:1276
   122		// accepts "@<target> HEAD" without a SHA and resolves the OID via
   123		// resolve_remote_symref.
   124		if target, ok := symrefs["HEAD"]; ok {
   125			if _, err := fmt.Fprintf(stdout, "@%s HEAD\n", target); err != nil {
   126				return fmt.Errorf("writing HEAD symref: %w", err)
   127			}
   128		} else if headValue != "" {
   129			if _, err := fmt.Fprintf(stdout, "%s HEAD\n", headValue); err != nil {
   130				return fmt.Errorf("writing HEAD: %w", err)
   131			}
   132		}
   133		if _, err := fmt.Fprintln(stdout); err != nil {
   134			return fmt.Errorf("writing terminator: %w", err)
   135		}
   136		return nil
   137	}
