 29	// IsV2Advertisement reports whether p begins with the v2 service
 30	// capability line ("version 2\n"). The peek is conservative: if the
 31	// length prefix is malformed or claims more bytes than p contains,
 32	// we return false rather than panic.
 33	func IsV2Advertisement(p []byte) bool {
 34		if len(p) < pktline.LenSize {
 35			return false
 36		}
 37		n, err := pktline.ParseLength(p[:pktline.LenSize])
 38		if err != nil || n < pktline.LenSize || len(p) < n {
 39			return false
 40		}
 41		return string(p[pktline.LenSize:n]) == "version 2\n"
 42	}
 43	
 44	// V2Command extracts the "command=" value from a v2 fetch / ls-refs /
 45	// bundle-uri request message. The message is the bytes between two
 46	// flushes (callers typically pass the buffer returned by
 47	// ReadFlushTerminatedMessage). Returns "" when the message is
 48	// malformed, truncated, or carries no command pktline.
 49	func V2Command(message []byte) string {
 50		for len(message) > 0 {
 51			if len(message) < pktline.LenSize {
 52				return ""
 53			}
 54			pktLen, err := pktline.ParseLength(message[:pktline.LenSize])
 55			if err != nil {
 56				return ""
 57			}
 58			switch pktLen {
 59			case pktline.Flush:
 60				return ""
 61			case pktline.Delim, pktline.ResponseEnd:
 62				message = message[pktline.LenSize:]
 63				continue
 64			}
 65			if pktLen < pktline.LenSize || len(message) < pktLen {
 66				return ""
 67			}
 68			line := string(message[pktline.LenSize:pktLen])
 69			if after, ok := strings.CutPrefix(line, "command="); ok {
 70				return strings.TrimSuffix(after, "\n")
 71			}
 72			message = message[pktLen:]
 73		}
 74		return ""
 75	}
