    10	// refAdvCache memoizes the receive-pack ref advertisement across a single
    11	// helper session so the "push" command reuses the exact ref snapshot that
    12	// "list for-push" fetched. This mirrors remote-curl.c's discovery cache
    13	// (get_refs/last_refs): Git builds its remote_refs list from the
    14	// "list for-push" advertisement, then runs the pre-push hook, then issues
    15	// "push". The Entire pre-push hook pushes per-checkpoint refs to the same
    16	// remote in that window, so a fresh info/refs at push time would hand
    17	// send-pack a ref Git never asked to push. send-pack then reports
    18	// `error <ref> no match` and Git — not finding it in remote_refs — warns
    19	// `helper reported unexpected status of <ref>` (ENCLI-267). Reusing the
    20	// snapshot keeps that phantom ref out of send-pack's view.
    21	//
    22	// Only the receive-pack (for-push) advertisement is cached; upload-pack and
    23	// v2 fetches pass straight through, matching remote-curl's per-for_push cache.
    24	type refAdvCache struct {
    25		receivePack []byte
    26		cached      bool
    27	}
    28	
    29	// infoRefs returns the ref advertisement for service. The receive-pack
    30	// advertisement is fetched from the Transport once and replayed from an
    31	// in-memory buffer on subsequent calls; every other service is fetched fresh.
    32	func (c *refAdvCache) infoRefs(ctx context.Context, t Transport, service string) (io.ReadCloser, error) {
    33		if service != serviceReceivePack {
    34			rc, err := t.InfoRefs(ctx, service)
    35			if err != nil {
    36				return nil, fmt.Errorf("fetch %s advertisement: %w", service, err)
    37			}
    38			return rc, nil
    39		}
    40		if c.cached {
    41			return io.NopCloser(bytes.NewReader(c.receivePack)), nil
    42		}
    43		rc, err := t.InfoRefs(ctx, service)
    44		if err != nil {
    45			return nil, fmt.Errorf("fetch %s advertisement: %w", service, err)
    46		}
    47		defer rc.Close()
    48		buf, err := io.ReadAll(rc)
    49		if err != nil {
    50			return nil, fmt.Errorf("buffer %s advertisement: %w", service, err)
    51		}
    52		c.receivePack = buf
    53		c.cached = true
    54		return io.NopCloser(bytes.NewReader(buf)), nil
    55	}
