// helperListResponse models how canonical git reads a "list" response.
// transport-helper.c's get_refs_list_internal calls recvline in a loop
// and stops at the first empty line; whatever follows stays buffered
// and is consumed as the response to the NEXT command git sends. After
// "list for-push" that command is "push", whose response is a batch of
// "ok <ref>" / "error <ref> <reason>" lines.
func helperListResponse(out string) (refLines []string, residue string) {
	rest := out
	for {
		line, tail, ok := strings.Cut(rest, "\n")
		if !ok {
			return refLines, line
		}
		if line == "" {
			return refLines, tail
		}
		refLines = append(refLines, line)
		rest = tail
	}
}

