// between the two framings handleList sits astride. The v0 advertisement
// it reads is pkt-line framed (length delimited), so a hostile server may
// put any byte in a ref name; the remote-helper protocol it writes is
// newline delimited with a blank line as terminator. Echoing the former
// into the latter lets the server truncate the ref list and plant a
// forged push result in the residue, so the advertisement must be
// rejected outright rather than emitted or quietly sanitised.
func TestHandleList_RejectsHostileRefAdvertisement(t *testing.T) {
	t.Parallel()

	const (
		mainSHA = testHeadSHA
		fooSHA  = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
		barSHA  = "cccccccccccccccccccccccccccccccccccccccc"
	)

