			// list early (dropping refs/heads/real), and "ok
			// refs/heads/main" lands exactly where git reads the reply
			// to the push it is about to issue.
			name:     "newline in ref name forges a push result",
			forPush:  true,
			service:  serviceReceivePack,
			firstRef: mainSHA + " refs/heads/main\x00report-status delete-refs object-format=sha1\n",
			more: []string{
				fooSHA + " refs/heads/evil\n\nok refs/heads/main\n",
				barSHA + " refs/heads/real\n",
			},
		},
		{
			name:     "newline in the capability-carrying first ref",
			service:  serviceUploadPack,
			firstRef: mainSHA + " refs/heads/main\nok refs/heads/main\x00symref=HEAD:refs/heads/main object-format=sha1\n",
			more:     []string{fooSHA + " refs/heads/foo\n"},
		},
		{
			// The OID half of the line is server-controlled too: it is
			// simply everything before the first space.
			name:     "newline in the advertised object ID",
			service:  serviceUploadPack,
			firstRef: mainSHA + " refs/heads/main\x00symref=HEAD:refs/heads/main object-format=sha1\n",
			more:     []string{fooSHA + "\nok refs/heads/main refs/heads/foo\n"},
		},
		{
			name:     "carriage return in ref name",
			service:  serviceUploadPack,
			firstRef: mainSHA + " refs/heads/main\x00symref=HEAD:refs/heads/main object-format=sha1\n",
			more:     []string{fooSHA + " refs/heads/foo\rok refs/heads/main\n"},
		},
		{
			name:     "NUL in ref name",
			service:  serviceUploadPack,
			firstRef: mainSHA + " refs/heads/main\x00symref=HEAD:refs/heads/main object-format=sha1\n",
			more:     []string{fooSHA + " refs/heads/foo\x00hidden\n"},
		},
