			// a newline — but NUL is not whitespace and the symref
			// target is echoed verbatim as "@<target> HEAD".
			name:     "NUL in symref target",
			service:  serviceUploadPack,
			firstRef: mainSHA + " HEAD\x00symref=HEAD:refs/heads/main\x00hidden object-format=sha1\n",
			more:     []string{mainSHA + " refs/heads/main\n"},
		},
		{
			name:     "NUL in object-format capability",
			service:  serviceUploadPack,
			firstRef: mainSHA + " refs/heads/main\x00object-format=sha1\x00hidden symref=HEAD:refs/heads/main\n",
			more:     nil,
		},
	}

