		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				var b bytes.Buffer
				b.WriteString(pktLine("# service=" + tt.service + "\n"))
				b.WriteString("0000")
				b.WriteString(pktLine(tt.firstRef))
				for _, ref := range tt.more {
					b.WriteString(pktLine(ref))
				}
				b.WriteString("0000")
				w.Header().Set("Content-Type", "application/x-"+tt.service+"-advertisement")
				_, _ = w.Write(b.Bytes()) //nolint:errcheck // test
			}))
			defer server.Close()

			var out bytes.Buffer
			err := handleList(context.Background(), testTransport(server), &refAdvCache{}, tt.forPush, &out)
			if err == nil {
				refLines, residue := helperListResponse(out.String())
				t.Fatalf("handleList accepted a hostile ref advertisement.\n"+
					"  git would read this ref list:            %q\n"+
					"  and leave this residue for the response\n"+
					"  to the next command it sends:            %q\n"+
					"  raw helper output:                       %q",
					refLines, residue, out.String())
			}
			if !errors.Is(err, errHostileAdvertisement) {
				t.Fatalf("handleList error = %v, want one wrapping errHostileAdvertisement", err)
			}
			if out.Len() != 0 {
				t.Errorf("handleList wrote %q before rejecting; a rejected advertisement must reach git as nothing at all", out.String())
			}
		})
	}
}
