package gitproto

import (
	"errors"
	"io"
	"strings"
	"testing"
)

func TestReadCapped(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		body    string
		limit   int64
		wantErr bool
	}{
		{name: "under the limit", body: "abcd", limit: 8},
		{name: "empty body", body: "", limit: 8},
		{name: "exactly on the limit", body: "abcdefgh", limit: 8},
		{name: "one byte over", body: "abcdefghi", limit: 8, wantErr: true},
		{name: "far over", body: strings.Repeat("x", 1024), limit: 8, wantErr: true},
		{name: "zero limit rejects any content", body: "a", limit: 0, wantErr: true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got, err := ReadCapped(strings.NewReader(tt.body), tt.limit, "test body")
			if tt.wantErr {
				if err == nil {
					t.Fatalf("ReadCapped(%d bytes, limit %d) = nil error, want ErrRemoteBodyTooLarge", len(tt.body), tt.limit)
				}
				if !errors.Is(err, ErrRemoteBodyTooLarge) {
					t.Fatalf("ReadCapped error = %v, want one wrapping ErrRemoteBodyTooLarge", err)
				}
				// The contract is failure, never truncation: a caller
				// that got a short buffer back would parse a prefix an
				// attacker chose the boundary of.
				if got != nil {
					t.Errorf("ReadCapped returned %d bytes alongside the error; it must return nothing so no caller can parse a truncated body", len(got))
				}
				return
			}
			if err != nil {
				t.Fatalf("ReadCapped: %v", err)
			}
			if string(got) != tt.body {
				t.Errorf("ReadCapped = %q, want %q", got, tt.body)
			}
		})
	}
}

// errReader fails partway through so ReadCapped's read-error path is
// covered distinctly from its over-limit path.
type errReader struct{ err error }

func (e errReader) Read([]byte) (int, error) { return 0, e.err }

func TestReadCapped_PropagatesReadError(t *testing.T) {
	t.Parallel()

	sentinel := errors.New("connection reset")
	got, err := ReadCapped(errReader{sentinel}, MaxAdvertisementBytes, "test body")
	if !errors.Is(err, sentinel) {
		t.Fatalf("ReadCapped error = %v, want one wrapping %v", err, sentinel)
	}
	if errors.Is(err, ErrRemoteBodyTooLarge) {
		t.Errorf("a read failure must not be reported as an over-limit body")
	}
	if got != nil {
		t.Errorf("ReadCapped returned %d bytes alongside a read error", len(got))
	}
}

// TestReadCapped_DoesNotBufferBeyondLimit guards the reason the helper
// exists at all: it must stop pulling from an endless reader instead of
// growing until the process dies.
func TestReadCapped_DoesNotBufferBeyondLimit(t *testing.T) {
	t.Parallel()

	const limit = 4096
	endless := &countingReader{}
	if _, err := ReadCapped(endless, limit, "endless body"); !errors.Is(err, ErrRemoteBodyTooLarge) {
		t.Fatalf("ReadCapped over an endless reader = %v, want ErrRemoteBodyTooLarge", err)
	}
	// limit+1 is what ReadCapped asks for; allow the io.ReadAll slack
	// of a single short read beyond it but nothing resembling unbounded.
	if endless.n > limit*2 {
		t.Errorf("ReadCapped consumed %d bytes for a %d-byte limit; it is not bounding the read", endless.n, limit)
	}
}

type countingReader struct{ n int }

func (c *countingReader) Read(p []byte) (int, error) {
	for i := range p {
		p[i] = 'x'
	}
	c.n += len(p)
	return len(p), nil
}

var _ io.Reader = (*countingReader)(nil)
GOEOF
