// TestHandleList_BoundsEndlessAdvertisement pins the memory bound on
// the ref advertisement. A server that simply never stops advertising
// refs used to grow the helper's buffers until the process died, on
// both routes into handleList: upload-pack reads a live stream and
// accumulates one entry per ref, while receive-pack is buffered whole
// by refAdvCache so the "push" that follows sees the same snapshot.
// Both must fail with ErrRemoteBodyTooLarge rather than run away.
func TestHandleList_BoundsEndlessAdvertisement(t *testing.T) {
	t.Parallel()

	// Advertise near-maximum pkt-lines (the wire limit is 65516 bytes
	// of payload) so the cap is reached in ~1k packets rather than
	// ~1M, keeping the test fast while exercising the real threshold.
	const refPayload = 60000
	// Enough packets to pass the cap roughly twice over, so a helper
	// that failed to bound would visibly overrun rather than stop by
	// coincidence at the end of the stream.
	maxPackets := 2*(gitproto.MaxAdvertisementBytes/refPayload) + 8

	tests := []struct {
		name    string
		forPush bool
		service string
	}{
		{name: "upload-pack streams into the ref loop", service: serviceUploadPack},
		{name: "receive-pack is buffered by refAdvCache", forPush: true, service: serviceReceivePack},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			hugeRef := testHeadSHA + " refs/heads/" +
				strings.Repeat("a", refPayload-len(testHeadSHA)-len(" refs/heads/")-1) + "\n"

			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				w.Header().Set("Content-Type", "application/x-"+tt.service+"-advertisement")
				var preamble bytes.Buffer
				preamble.WriteString(pktLine("# service=" + tt.service + "\n"))
				preamble.WriteString("0000")
				preamble.WriteString(pktLine(testHeadSHA + " refs/heads/main\x00object-format=sha1\n"))
				if _, err := w.Write(preamble.Bytes()); err != nil {
					return
				}
				packet := pktLine(hugeRef)
				for range maxPackets {
					if _, err := io.WriteString(w, packet); err != nil {
						return
					}
					select {
					case <-r.Context().Done():
						return
					default:
					}
				}
			}))
			defer server.Close()

			var out bytes.Buffer
			err := handleList(context.Background(), testTransport(server), &refAdvCache{}, tt.forPush, &out)
			if !errors.Is(err, gitproto.ErrRemoteBodyTooLarge) {
				t.Fatalf("handleList over an endless advertisement = %v, want ErrRemoteBodyTooLarge", err)
			}
			if out.Len() != 0 {
				t.Errorf("handleList wrote %d bytes before bailing; a rejected advertisement must reach git as nothing at all", out.Len())
			}
		})
	}
}
